def solve(grid):
    import copy

    # Create a copy of the grid to work with
    result = copy.deepcopy(grid)
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Find all 2s in the grid
    twos = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                twos.append((r, c))

    # For each pair of 2s, check if they form a rectangle and fill with 3s
    for i in range(len(twos)):
        for j in range(i + 1, len(twos)):
            r1, c1 = twos[i]
            r2, c2 = twos[j]

            # Check if they form a rectangle (different row and column)
            if r1 != r2 and c1 != c2:
                # Check if the other two corners are also 2s
                # Corner 1: (r1, c2)
                # Corner 2: (r2, c1)
                if grid[r1][c2] == 2 and grid[r2][c1] == 2:
                    # Found a rectangle! Fill edges with 3s

                    # Determine bounds
                    min_r = min(r1, r2)
                    max_r = max(r1, r2)
                    min_c = min(c1, c2)
                    max_c = max(c1, c2)

                    # Fill horizontal edges with 3s (where there isn't a 2)
                    for c in range(min_c, max_c + 1):
                        # Top edge
                        if result[min_r][c] == 0:
                            result[min_r][c] = 3
                        # Bottom edge
                        if result[max_r][c] == 0:
                            result[max_r][c] = 3

                    # Fill vertical edges with 3s (where there isn't a 2)
                    for r in range(min_r, max_r + 1):
                        # Left edge
                        if result[r][min_c] == 0:
                            result[r][min_c] = 3
                        # Right edge
                        if result[r][max_c] == 0:
                            result[r][max_c] = 3

    return result
